create or replace function public.list_deleted_transactions(p_family_id uuid,p_limit int default 50,p_offset int default 0,p_query text default '',p_transaction_type text default '',p_purpose_id uuid default null,p_expense_type_id uuid default null,p_payment_method_id uuid default null,p_month int default null,p_year int default null,p_date_from date default null,p_date_to date default null) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare result jsonb; begin if not public.is_family_member(p_family_id) then raise exception 'FORBIDDEN'; end if; if p_limit<1 or p_limit>100 or p_offset<0 then raise exception 'INVALID_PAGE'; end if; with base as (select t.* from public.transactions t where t.family_id=p_family_id and t.deleted_at is not null and (public.is_family_owner(p_family_id) or t.created_by=auth.uid()) and (trim(p_query)='' or t.description ilike '%'||trim(p_query)||'%' or coalesce(t.note,'') ilike '%'||trim(p_query)||'%') and (p_transaction_type='' or t.transaction_type::text=p_transaction_type) and (p_purpose_id is null or t.purpose_id=p_purpose_id) and (p_expense_type_id is null or t.expense_type_id=p_expense_type_id) and (p_payment_method_id is null or t.payment_method_id=p_payment_method_id) and (p_month is null or extract(month from t.transaction_date)::int=p_month) and (p_year is null or extract(year from t.transaction_date)::int=p_year) and (p_date_from is null or t.transaction_date>=p_date_from) and (p_date_to is null or t.transaction_date<=p_date_to)), filtered as (select * from base order by deleted_at desc,id limit p_limit+1 offset p_offset), page as (select * from filtered limit p_limit) select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(p)) from page p),'[]'::jsonb),'hasMore',(select count(*)>p_limit from filtered),'totalCount',(select count(*) from base)) into result; return result; end $$;
revoke all on function public.list_deleted_transactions(uuid,int,int,text,text,uuid,uuid,uuid,int,int,date,date) from public;
grant execute on function public.list_deleted_transactions(uuid,int,int,text,text,uuid,uuid,uuid,int,int,date,date) to authenticated;
